// This code takes an array where each item has an "output" array
// It flattens all inner "output" entries into separate items

const results = [];

for (const item of $input.all()) {
  const outputs = item.json.output;
  for (const entry of outputs) {
    results.push({ json: entry });
  }
}

return results;
